package com.pethop.security;
import com.pethop.user.User; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import org.hibernate.annotations.UuidGenerator;
@Entity @Table(name="email_verification_tokens") public class EmailVerificationToken{ @Id @UuidGenerator private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="token_hash",nullable=false,unique=true,length=64) private String tokenHash; @Column(name="expires_at",nullable=false) private Instant expiresAt; @Column(name="used_at") private Instant usedAt; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @PrePersist void onCreate(){createdAt=Instant.now();} public UUID getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getTokenHash(){return tokenHash;} public void setTokenHash(String v){tokenHash=v;} public Instant getExpiresAt(){return expiresAt;} public void setExpiresAt(Instant v){expiresAt=v;} public Instant getUsedAt(){return usedAt;} public void setUsedAt(Instant v){usedAt=v;} }
